libraries.usage:
#include "mcu_gpio.h"

PeripheralClockEnable(GPIOB);
GPIO_Write(GPIOB, 1, false);  // Ausgangswert vor dem Umschalten setzen
GPIO_Mode(GPIOB, 1, PushPull);
GPIO_Pull(GPIOB, 1, NoPull);
GPIO_Write(GPIOB, 1, true);
GPIO_Toggle(GPIOB, 1);

// Eingang: GPIO_Mode(GPIOA, 0, Input);
// GPIO_Pull(GPIOA, 0, PullUp);
// bool high = GPIO_Read(GPIOA, 0);

#include "mcu_uart.h"

// Pins vorher passend zur Instanz konfigurieren!
// USART1: PA9 TX, PA10 RX, AF7; PCLK2 = 16 MHz im Reset-Demo.
if (!UART_Init(USART1, 16000000, 115200)) { /* Fehler behandeln */ }
UART_Print(USART1, "Hallo!\r\n", 100000);
uint8_t byte;
if (UART_TryRead(USART1, &byte) == UART_Ok) {
  UART_Write(USART1, &byte, 1, 100000);
}
// Andere Instanz: UART_Init(USART2, pclk1Hz, baud);
// UART_Flush wartet zusätzlich bis zur letzten gesendeten Stoppbit-Zeit.

#include "mcu_can.h"

if (!CAN_Init(FDCAN1, 16000000, 500000, CAN_InternalLoopback)) { /* Fehler */ }
CAN_Message tx = {0};
tx.id = 0x123;
tx.length = 2;
tx.data[0] = 42;
tx.data[1] = 7;
CAN_Result result = CAN_Send(FDCAN1, &tx); // Ok = eingereiht, nicht ACK
CAN_Message rx;
if (CAN_Receive(FDCAN1, &rx) == CAN_Ok) { /* rx.data verwenden */ }
// CAN_Normal: PB8 RX + PB9 TX, AF9, externer CAN-Transceiver nötig.
// Polling regelmäßig aufrufen; CAN_TakeOverflow meldet verlorene Frames.

#include "mcu_gpio.h"

GPIO led(GPIOB, 1);
led.enableClock();
led.write(false);
led.mode(GPIO::PushPull);
led.pull(GPIO::NoPull);
led.toggle();

#include "mcu_uart.h"

UART serial(USART1);
// Configure PA9/PA10 AF7 first. Actual PCLK2 = 16 MHz.
if (serial.begin(16000000, 115200)) {
  serial.print("Hallo\r\n", 100000);
  uint8_t byte;
  if (serial.tryRead(byte) == UART::Ok) serial.tryWrite(byte);
}

#include "mcu_can.h"

CAN bus(FDCAN1);
if (bus.begin(16000000, 500000, CAN::InternalLoopback)) {
  CAN::Message frame;
  frame.id = 0x123;
  frame.length = 1;
  frame.data[0] = 42;
  bus.send(frame);
  CAN::Message received;
  if (bus.receive(received) == CAN::Ok) { /* use received.data */ }
}

